import { Transform, type TransformCallback, type Writable } from "node:stream";

export interface AggregatorOptions {
  readonly highWaterMark?: number;
  readonly batchSize?: number;
  readonly flushIntervalMs?: number;
}

export interface MetricItem {
  readonly id: string;
  readonly timestamp: number;
  readonly value: number;
  readonly tags: Record<string, string>;
}

export interface AggregatedBatch {
  readonly batchId: string;
  readonly count: number;
  readonly totalValue: number;
  readonly averageValue: number;
  readonly items: readonly MetricItem[];
  readonly createdAt: number;
}

export class StreamAggregator extends Transform {
  private buffer: MetricItem[] = [];
  private readonly batchSize: number;
  private readonly flushIntervalMs: number;
  private timer: NodeJS.Timeout | null = null;
  private batchCounter = 0;
  private downstream: Writable | null = null;

  constructor(options: AggregatorOptions = {}) {
    super({
      objectMode: true,
      highWaterMark: options.highWaterMark ?? 64,
    });
    this.batchSize = options.batchSize ?? 100;
    this.flushIntervalMs = options.flushIntervalMs ?? 1000;
    this.startPeriodicFlush();
  }

  public setDownstream(writable: Writable): void {
    this.downstream = writable;
  }

  private startPeriodicFlush(): void {
    if (this.timer) {
      clearInterval(this.timer);
    }
    this.timer = setInterval(() => {
      if (this.buffer.length > 0) {
        this.flushBuffer();
      }
    }, this.flushIntervalMs);
  }

  _transform(
    chunk: MetricItem,
    _encoding: BufferEncoding,
    callback: TransformCallback
  ): void {
    this.buffer.push(chunk);
    if (this.buffer.length >= this.batchSize) {
      this.flushBuffer();
    }
    callback();
  }

  _flush(callback: TransformCallback): void {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
    if (this.buffer.length > 0) {
      this.flushBuffer();
    }
    callback();
  }

  private flushBuffer(): void {
    if (this.buffer.length === 0) return;
    const currentItems = this.buffer;
    this.buffer = [];
    this.batchCounter += 1;
    const total = currentItems.reduce((acc, item) => acc + item.value, 0);
    const batch: AggregatedBatch = {
      batchId: `batch-${this.batchCounter}-${Date.now()}`,
      count: currentItems.length,
      totalValue: total,
      averageValue: currentItems.length > 0 ? total / currentItems.length : 0,
      items: currentItems,
      createdAt: Date.now(),
    };

    if (this.downstream) {
      this.downstream.write(batch);
    } else {
      this.push(batch);
    }
  }

  public getPendingBufferSize(): number {
    return this.buffer.length;
  }

  public destroy(error?: Error): this {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
    return super.destroy(error);
  }
}

