import { EventEmitter } from "node:events";

export interface PipelineEvent {
  readonly topic: string;
  readonly payload: unknown;
  readonly timestamp: number;
  readonly traceId: string;
}

export type EventHandler = (event: PipelineEvent) => void | Promise<void>;

export interface SubscriptionHandle {
  readonly subscriptionId: string;
  readonly topic: string;
  readonly unsubscribe: () => void;
}

export class PipelineEventHub {
  private readonly emitter = new EventEmitter();
  private readonly subscriptions = new Map<string, { topic: string; handler: EventHandler }>();
  private readonly retainedEventHistory: PipelineEvent[] = [];
  private subscriptionCounter = 0;

  constructor(maxListeners = 0) {
    this.emitter.setMaxListeners(maxListeners);
  }

  public subscribe(topic: string, handler: EventHandler): SubscriptionHandle {
    this.subscriptionCounter += 1;
    const subscriptionId = `sub-${this.subscriptionCounter}-${Date.now()}`;

    const wrappedHandler: EventHandler = (event: PipelineEvent) => {
      this.retainedEventHistory.push(event);
      return handler(event);
    };

    this.emitter.on(topic, wrappedHandler);
    this.subscriptions.set(subscriptionId, { topic, handler: wrappedHandler });

    return {
      subscriptionId,
      topic,
      unsubscribe: () => {
        this.subscriptions.delete(subscriptionId);
      },
    };
  }

  public publish(topic: string, payload: unknown, traceId = ""): boolean {
    const event: PipelineEvent = {
      topic,
      payload,
      timestamp: Date.now(),
      traceId: traceId || `trace-${Math.random().toString(36).substring(2, 11)}`,
    };
    return this.emitter.emit(topic, event);
  }

  public getActiveSubscriptionCount(): number {
    return this.subscriptions.size;
  }

  public getRawListenerCount(topic: string): number {
    return this.emitter.listenerCount(topic);
  }

  public clearHistory(): void {
    this.retainedEventHistory.length = 0;
  }
}

