export interface MemorySnapshot {
  readonly timestamp: number;
  readonly heapUsedMB: number;
  readonly heapTotalMB: number;
  readonly rssMB: number;
  readonly externalMB: number;
  readonly arrayBuffersMB: number;
}

export interface LeakDiagnosticReport {
  readonly durationMs: number;
  readonly initialHeapMB: number;
  readonly finalHeapMB: number;
  readonly deltaHeapMB: number;
  readonly growthRateMBPerSec: number;
  readonly isLeakSuspected: boolean;
  readonly snapshotCount: number;
}

export class PipelineMemoryMonitor {
  private readonly snapshots: MemorySnapshot[] = [];
  private samplingInterval: NodeJS.Timeout | null = null;
  private readonly growthThresholdMB: number;

  constructor(growthThresholdMB = 50) {
    this.growthThresholdMB = growthThresholdMB;
  }

  public captureSnapshot(): MemorySnapshot {
    const mem = process.memoryUsage();
    const bytesToMB = (bytes: number) => Math.round((bytes / 1024 / 1024) * 100) / 100;
    const snapshot: MemorySnapshot = {
      timestamp: Date.now(),
      heapUsedMB: bytesToMB(mem.heapUsed),
      heapTotalMB: bytesToMB(mem.heapTotal),
      rssMB: bytesToMB(mem.rss),
      externalMB: bytesToMB(mem.external),
      arrayBuffersMB: bytesToMB(mem.arrayBuffers ?? 0),
    };
    this.snapshots.push(snapshot);
    return snapshot;
  }

  public startSampling(intervalMs = 500): void {
    if (this.samplingInterval) {
      clearInterval(this.samplingInterval);
    }
    this.captureSnapshot();
    this.samplingInterval = setInterval(() => {
      this.captureSnapshot();
    }, intervalMs);
  }

  public stopSampling(): LeakDiagnosticReport {
    if (this.samplingInterval) {
      clearInterval(this.samplingInterval);
      this.samplingInterval = null;
    }
    this.captureSnapshot();

    if (this.snapshots.length === 0) {
      return {
        durationMs: 0,
        initialHeapMB: 0,
        finalHeapMB: 0,
        deltaHeapMB: 0,
        growthRateMBPerSec: 0,
        isLeakSuspected: false,
        snapshotCount: 0,
      };
    }

    const first = this.snapshots[0];
    const last = this.snapshots[this.snapshots.length - 1];
    const durationMs = Math.max(1, last.timestamp - first.timestamp);
    const deltaHeapMB = Math.round((last.heapUsedMB - first.heapUsedMB) * 100) / 100;
    const growthRateMBPerSec = Math.round((deltaHeapMB / (durationMs / 1000)) * 100) / 100;
    const isLeakSuspected = deltaHeapMB > this.growthThresholdMB;

    return {
      durationMs,
      initialHeapMB: first.heapUsedMB,
      finalHeapMB: last.heapUsedMB,
      deltaHeapMB,
      growthRateMBPerSec,
      isLeakSuspected,
      snapshotCount: this.snapshots.length,
    };
  }

  public getSnapshots(): readonly MemorySnapshot[] {
    return [...this.snapshots];
  }

  public reset(): void {
    if (this.samplingInterval) {
      clearInterval(this.samplingInterval);
      this.samplingInterval = null;
    }
    this.snapshots.length = 0;
  }
}
